<?php require __DIR__.'/../layouts/header.php'; ?><h1>Product Management</h1><p><a class="btn" href="<?= BASE_URL ?>/?action=create">Add Product</a> <a class="btn secondary" href="<?= BASE_URL ?>/?page=customer">Register Customer</a></p><section class="panel"><table class="table"><tr><th>Name</th><th>Price</th><th>Quantity</th><th>Image</th></tr><?php foreach($products as $p): ?><tr><td><?= e($p['name']) ?></td><td><?= e($p['price']) ?></td><td><?= e($p['quantity']) ?></td><td><?php if($p['image_name']): ?><img width="65" src="<?= BASE_URL ?>/uploads/<?= e($p['image_name']) ?>"><?php endif; ?></td></tr><?php endforeach; ?></table></section><?php require __DIR__.'/../layouts/footer.php'; ?>